import assert from "node:assert/strict";
import { lstatSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { spawnSync } from "node:child_process";

const [actionDir, repositoryRoot, probeRoot] = process.argv.slice(2).map(value => resolve(value));
const actionSha = "b906affcce14559ad1aafd4ab0e942779e9f58b1";
const copyDigest = "1035f2eb5777a23c91e99de2b9d585c6bffa7f2350873225858eded00453f3e4";
const version = "11.0.8";
const { resolveActionPnpm } = await import(pathToFileURL(join(repositoryRoot, "scripts/release/pnpm-runner.mjs")));
const { capturePackTreeIdentity, normalizedTreeSha256 } = await import(pathToFileURL(join(repositoryRoot, "tools/packaging/pack-tool-identity.ts")));

function boundedHostEnv() {
  const env = {};
  for (const key of ["Path", "SystemRoot", "ComSpec", "PATHEXT", "TEMP", "TMP", "USERPROFILE", "LOCALAPPDATA", "APPDATA", "ProgramFiles"]) {
    if (process.env[key]) env[key] = process.env[key];
  }
  return env;
}

function install(name, copy) {
  const runRoot = join(probeRoot, name);
  const dest = join(runRoot, "setup-pnpm");
  rmSync(runRoot, { force: true, recursive: true });
  mkdirSync(runRoot, { recursive: true });
  const files = Object.fromEntries(["env", "path", "output", "state"].map(key => {
    const path = join(runRoot, `github-${key}`);
    writeFileSync(path, "");
    return [key, path];
  }));
  const env = {
    ...boundedHostEnv(), CI: "true", GITHUB_ACTIONS: "true", GITHUB_WORKSPACE: repositoryRoot,
    GITHUB_ENV: files.env, GITHUB_PATH: files.path, GITHUB_OUTPUT: files.output, GITHUB_STATE: files.state,
    RUNNER_OS: "Windows", RUNNER_TEMP: runRoot, INPUT_VERSION: version, INPUT_DEST: dest,
    INPUT_RUN_INSTALL: "null", INPUT_CACHE: "false", INPUT_CACHE_DEPENDENCY_PATH: "pnpm-lock.yaml",
    INPUT_PACKAGE_JSON_FILE: "package.json", INPUT_STANDALONE: "false",
    ...(copy ? { NPM_CONFIG_PACKAGE_IMPORT_METHOD: "copy" } : {}),
  };
  const ran = spawnSync(process.execPath, [join(actionDir, "dist/index.js")], {
    cwd: actionDir, encoding: "utf8", env, maxBuffer: 16 * 1024 * 1024, shell: false, timeout: 180_000,
  });
  assert.equal(ran.error, undefined, `${name} spawn failed`);
  assert.equal(ran.status, 0, `${name} action failed: ${ran.stderr.slice(-500)}`);
  const home = join(dest, "node_modules", ".bin");
  const packageRoot = join(dest, "node_modules", "pnpm");
  const manifest = JSON.parse(readFileSync(join(packageRoot, "package.json"), "utf8"));
  assert.equal(manifest.version, version);
  return { environment: { PNPM_HOME: home }, packageRoot };
}

function denominator(root) {
  let directories = 0, files = 0, hardlinks = 0;
  const pending = [root];
  while (pending.length) {
    const current = pending.pop();
    directories++;
    for (const entry of readdirSync(current, { withFileTypes: true })) {
      const path = join(current, entry.name);
      if (entry.isDirectory()) pending.push(path);
      else if (entry.isFile()) { files++; if (lstatSync(path).nlink > 1) hardlinks++; }
    }
  }
  assert.ok(files > 0);
  return { directories, files, hardlinks };
}

const rev = spawnSync("git", ["-C", actionDir, "rev-parse", "HEAD"], { encoding: "utf8", shell: false });
assert.equal(rev.status, 0);
assert.equal(rev.stdout.trim(), actionSha);
const layouts = [install("default", false), install("copy", true)];
assert.equal(layouts.length, 2);
const defaultRefusal = resolveActionPnpm({ environment: layouts[0].environment, repositoryRoot });
assert.deepEqual(defaultRefusal, { code: "RELEASE_SUPPLY_CHAIN_REFUSED", ok: false, reason: "TOOLCHAIN_OBSERVATION_FAILED", refusedBy: "RELEASE_SUPPLY_CHAIN" });
const digest = normalizedTreeSha256(capturePackTreeIdentity(layouts[1].packageRoot));
assert.equal(digest, copyDigest);
const copyRefusal = resolveActionPnpm({ environment: layouts[1].environment, repositoryRoot });
assert.deepEqual(copyRefusal, { code: "RELEASE_SUPPLY_CHAIN_REFUSED", ok: false, reason: "TOOLCHAIN_IDENTITY_MISMATCH", refusedBy: "RELEASE_SUPPLY_CHAIN" });
console.log(JSON.stringify({ actionSha, version, materializations: [
  { kind: "default", ...denominator(layouts[0].packageRoot), refusal: defaultRefusal },
  { kind: "copy", ...denominator(layouts[1].packageRoot), digest, refusal: copyRefusal },
] }, null, 2));
